export const MATERIALS={paper:{name:'Paper & cardboard',icon:'▤',rule:'Clean, dry and flattened. No greasy food boxes.'},plastic:{name:'PET bottles',icon:'♧',rule:'Empty and rinsed PET #1 drink bottles. No mixed plastics.'},metal:{name:'Aluminium cans',icon:'◉',rule:'Empty, rinsed beverage cans. No aerosols or paint tins.'}};
export const WINDOWS=['24 Oct 2026 · 09:00–12:00','24 Oct 2026 · 14:00–17:00','25 Oct 2026 · 09:00–12:00'];
export const POINTS=[{id:'p1',name:'Meranti Court',x:1.2,y:1.1},{id:'p2',name:'Lakeview Terrace',x:2.4,y:0.8},{id:'p3',name:'Kenanga Lane',x:3.4,y:1.5},{id:'p4',name:'Garden Residences',x:3.7,y:2.8},{id:'p5',name:'Community Garden',x:2.5,y:3.4},{id:'p6',name:'Serai Walk',x:1.1,y:2.8},{id:'p7',name:'Parkside Court',x:2.1,y:2.1},{id:'p8',name:'Banyan Place',x:4.4,y:3.8}];
export const DEPOT={x:0.4,y:0.4,name:'Collector hub'};
export const CAPACITY=150;
export const distance=(a,b)=>Math.abs(a.x-b.x)+Math.abs(a.y-b.y);
export const point=r=>POINTS.find(p=>p.id===r.pointId);
export function routeDistance(stops){const p=[DEPOT,...stops.map(point),DEPOT];return p.slice(1).reduce((s,v,i)=>s+distance(p[i],v),0);}
export function optimise(requests){let remaining=[...requests],route=[],at=DEPOT;while(remaining.length){remaining.sort((a,b)=>distance(at,point(a))-distance(at,point(b))||a.id.localeCompare(b.id));const next=remaining.shift();route.push(next);at=point(next);}let improved=true;while(improved){improved=false;for(let i=0;i<route.length-1;i++)for(let j=i+1;j<route.length;j++){const candidate=[...route.slice(0,i),...route.slice(i,j+1).reverse(),...route.slice(j+1)];if(routeDistance(candidate)<routeDistance(route)-0.00001){route=candidate;improved=true;}}}return route;}
export function plan(requests){const groups=[];for(const window of WINDOWS){const eligible=requests.filter(r=>r.window===window&&r.status==='pending'&&MATERIALS[r.material]);let batch=[],kg=0;for(const r of eligible){if(kg+r.estimated>CAPACITY&&batch.length){groups.push({window,stops:optimise(batch)});batch=[];kg=0;}batch.push(r);kg+=r.estimated;}if(batch.length)groups.push({window,stops:optimise(batch)});}return groups.map((g,i)=>({...g,index:i,km:routeDistance(g.stops),baseline:g.stops.reduce((s,r)=>s+2*distance(DEPOT,point(r)),0),estimated:g.stops.reduce((s,r)=>s+r.estimated,0)}));}
export function validateBooking(input){if(!MATERIALS[input.material])throw Error('This collector does not accept that material.');if(!POINTS.some(p=>p.id===input.pointId))throw Error('Choose a collection point in the pilot neighbourhood.');if(!WINDOWS.includes(input.window))throw Error('Choose an available collection window.');const estimated=Number(input.estimated);if(!Number.isFinite(estimated)||estimated<0.1||estimated>30)throw Error('Enter an estimated weight between 0.1 and 30 kg.');if(!input.prepared)throw Error('Confirm that the material follows the preparation guide.');return {material:input.material,pointId:input.pointId,window:input.window,estimated,status:'pending',source:'User demo booking'};}
export function recordOutcome(request,input){if(request.status!=='scheduled')throw Error('Only a scheduled collection can be recorded.');const accepted=Number(input.accepted),rejected=Number(input.rejected);if(!Number.isFinite(accepted)||!Number.isFinite(rejected)||accepted<0||rejected<0||accepted+rejected>150)throw Error('Weights must be between 0 and 150 kg in total.');if(!['collected','rejected','missed'].includes(input.outcome))throw Error('Choose an outcome.');if(input.outcome==='collected'&&accepted<=0)throw Error('A completed collection needs a positive accepted weight.');if(input.outcome!=='collected'&&accepted!==0)throw Error('Rejected or missed collections must have zero accepted weight.');if(input.outcome==='rejected'&&rejected<=0)throw Error('Enter the rejected weight.');if(input.outcome==='missed'&&rejected!==0)throw Error('A missed pickup has no inspected material.');if((rejected>0||input.outcome==='missed')&&!input.reason?.trim())throw Error('Add a reason for rejected material or a missed pickup.');return {...request,status:input.outcome,accepted,rejected,reason:(input.reason||'').trim().slice(0,200),recordedAt:new Date().toISOString()};}
export function metrics(requests){const closed=requests.filter(r=>['collected','rejected','missed'].includes(r.status));const collected=closed.filter(r=>r.status==='collected');const accepted=closed.reduce((s,r)=>s+(r.accepted||0),0),rejected=closed.reduce((s,r)=>s+(r.rejected||0),0);return{accepted,rejected,closed:closed.length,collected:collected.length,completion:closed.length?collected.length/closed.length*100:null,rejection:accepted+rejected?rejected/(accepted+rejected)*100:null};}
export function seed(){const weights=[6,4,8,3,12,5,9,7,4,11,6,8];return {version:1,requests:weights.map((estimated,i)=>({id:'RL-'+String(i+1).padStart(3,'0'),material:['paper','plastic','metal'][i%3],pointId:POINTS[i%8].id,window:WINDOWS[i<8?0:1],estimated,status:'pending',source:'Synthetic request'})),rounds:[]};}
export function csv(requests){const columns=['id','source','material','pointId','window','status','estimated','accepted','rejected','reason','roundId','recordedAt'];const escape=value=>'"'+String(value??'').replace(/^[=+@-]/,"' $&").replaceAll('"','""')+'"';return [columns,...requests.map(r=>columns.map(c=>r[c]))].map(row=>row.map(escape).join(',')).join('\r\n');}
